update public.learning_paths
set
  title = 'Acting II',
  goal = 'Acting II',
  summary = 'Acting II develops the actor''s craft through sustained scene study, character development, partner responsiveness, and rehearsal process. Building on Acting I, students learn to analyze scripts for playable action, build specific characters, pursue objectives through obstacles, work truthfully moment to moment, and present contemporary realist scenes with vocal, physical, emotional, and relational clarity. The course prepares students for Acting III, period/style work, auditions, production practicum, directing collaboration, and more advanced performance contexts.',
  data = $act2json${"slug": "acting-ii", "title": "Acting II", "description": "Acting II develops the actor's craft through sustained scene study, character development, partner responsiveness, and rehearsal process. Building on Acting I, students learn to analyze scripts for playable action, build specific characters, pursue objectives through obstacles, work truthfully moment to moment, and present contemporary realist scenes with vocal, physical, emotional, and relational clarity. The course prepares students for Acting III, period/style work, auditions, production practicum, directing collaboration, and more advanced performance contexts.", "topics": [{"id": "1593353c-b161-4670-8ca8-bf479b4a6152", "type": "topic", "title": "Script Analysis for the Actor", "description": "Acting II asks students to read scripts as maps for behavior. This unit turns analysis into playable choices rather than literary summary.", "children": [{"id": "ae223e02-b50f-4154-acae-912ee4f1019a", "type": "subtopic", "title": "Given Circumstances", "children": [{"id": "030b0544-4da5-4a79-8c19-b28b58ce4994", "type": "concept", "title": "Who, where, when, what just happened, and what is at stake"}, {"id": "7b917b15-2c29-4523-a27d-5ba4cd00e6c2", "type": "concept", "title": "Social, economic, cultural, and historical pressures"}, {"id": "0ce5ca4b-2fc8-4182-abfb-20bafe842eea", "type": "concept", "title": "Research that changes action"}], "description": "Actors locate the facts that shape behavior."}, {"id": "c87777c3-2e89-4e63-a3e4-c82cf817f102", "type": "subtopic", "title": "Events and Turning Points", "children": [{"id": "925a9f5c-5fd1-4b33-bb00-772b1075a162", "type": "concept", "title": "Inciting incident within the scene"}, {"id": "3633b54b-5003-49ed-a24d-141dbc0515c4", "type": "concept", "title": "Discoveries, reversals, entrances, exits, and interruptions"}, {"id": "715f3036-a5d9-438c-a332-64fed0f3902a", "type": "concept", "title": "Event-based rehearsal notes"}], "description": "Students identify where the scene actually changes."}, {"id": "948a7036-4d6a-442b-973c-b4ec3154be98", "type": "subtopic", "title": "Actor Questions", "children": [{"id": "c489da57-202c-457c-9b73-ae096a34ca5a", "type": "concept", "title": "What do I want?"}, {"id": "4623ae63-6358-4fed-a91c-4470b6518b8e", "type": "concept", "title": "What am I doing to get it?"}, {"id": "99668b77-b3e7-4c0e-b938-b17bc64357cd", "type": "concept", "title": "What changes my tactic?"}], "description": "The goal is to ask questions that can be tested in rehearsal."}]}, {"id": "d02dc780-5a7c-4d02-817a-c60c71965495", "type": "topic", "title": "Building a Character", "description": "Character work deepens from Acting I by connecting research, imagination, behavior, body, voice, and relationship into a repeatable performance score.", "children": [{"id": "627f686c-c74b-476a-bd6c-84a7affc4c85", "type": "subtopic", "title": "Character Need and History", "children": [{"id": "970a8d78-a9d4-444f-85f0-3edddb5088e0", "type": "concept", "title": "Need, wound, fear, dream, secret, and contradiction"}, {"id": "f5977dd0-f6af-4411-a781-377d111ea016", "type": "concept", "title": "Public self versus private self"}, {"id": "f8e40cac-d2d1-4c8a-9d40-55b041baf826", "type": "concept", "title": "Backstory as playable pressure"}], "description": "Students build biography only where it feeds behavior."}, {"id": "cea7cd53-0de5-4967-a358-9c8944cc787e", "type": "subtopic", "title": "Relationship Web", "children": [{"id": "c7a5a95a-b2ed-4346-97c4-cf23ceb823f6", "type": "concept", "title": "Power, intimacy, dependence, rivalry, debt, and loyalty"}, {"id": "fb4ef37b-6294-4ea6-94d1-413f3de0bac7", "type": "concept", "title": "What each character knows and withholds"}, {"id": "058869f7-4819-4eae-8292-471a25ac895e", "type": "concept", "title": "Relationship before the first line"}], "description": "Characters are built through other people."}, {"id": "f94a6b11-fa81-462c-a8e3-8e944a32cd76", "type": "subtopic", "title": "Behavioral Specificity", "children": [{"id": "b6b4d84e-6f15-4385-bc67-f2f7a54f064b", "type": "concept", "title": "Habits, rituals, objects, posture, pace, and listening style"}, {"id": "dca3d171-d0a8-4581-9ed3-639ef7fb0208", "type": "concept", "title": "Avoiding stereotype and generalized mood"}, {"id": "139d1224-4356-41d4-bf15-e0ebd786f9af", "type": "concept", "title": "Repeatable choices with room for discovery"}], "description": "The point is to make character visible through action."}]}, {"id": "708e0096-154b-4d0a-8b6d-0aebb2641af1", "type": "topic", "title": "Objectives, Obstacles, and Tactics", "description": "This is the engine of scene study. Students refine wants and tactical behavior until scenes have pressure, clarity, and responsiveness.", "children": [{"id": "27e6c89c-a8b7-4ad4-94e2-03f4f58b04c0", "type": "subtopic", "title": "Scene Objective", "children": [{"id": "435ea529-aeab-4851-ad18-b18411ef8b48", "type": "concept", "title": "Playable, partner-directed objectives"}, {"id": "ef4e70cd-9f1b-49e7-b8df-4ed51a5b0cb5", "type": "concept", "title": "Stakes and consequences"}, {"id": "43164a1f-e1a6-4bcb-a335-6f84a4f460de", "type": "concept", "title": "Objective versus mood or theme"}], "description": "Actors choose wants that organize the whole scene."}, {"id": "f6e6295d-c703-4544-8af3-382624047814", "type": "subtopic", "title": "Obstacles", "children": [{"id": "e1ca31b4-34b5-4412-808e-1832cb8aa26b", "type": "concept", "title": "External, internal, relational, and social obstacles"}, {"id": "e0a05083-4c8a-4a7f-ba45-2caa30818758", "type": "concept", "title": "What the partner blocks or offers"}, {"id": "640cb4cd-1380-4710-b175-dc071901c143", "type": "concept", "title": "How obstacles raise stakes"}], "description": "Students learn that resistance creates action."}, {"id": "469f63e6-d536-48db-b527-137216b08b5e", "type": "subtopic", "title": "Tactical Shifts", "children": [{"id": "90872651-9513-4c05-8330-ac9cc52f9b5e", "type": "concept", "title": "Action verbs"}, {"id": "4cbc1549-74d7-49a2-b3d1-332c9ee6fbfd", "type": "concept", "title": "Escalation, retreat, charm, attack, bargain, comfort"}, {"id": "4176b23c-0145-4928-a769-10a346e35ec5", "type": "concept", "title": "Tactic shifts at beat changes"}], "description": "Actors practice changing strategy when circumstances change."}]}, {"id": "55825b51-cf0e-4b4c-b403-40e38e6b91c3", "type": "topic", "title": "Scene Study: Contemporary Realism", "description": "Contemporary realism trains truthful behavior in recognizable circumstances. Students learn that ordinary behavior can be theatrically charged when stakes are specific.", "children": [{"id": "1a15c003-95a7-4943-8b17-edc8bc712dee", "type": "subtopic", "title": "Realist Circumstances", "children": [{"id": "a306efc7-36b4-48be-8059-4b5210ef7b13", "type": "concept", "title": "Domestic space, work, family, money, time, and social pressure"}, {"id": "ca589a60-5fb3-45d0-bbe0-7889c7935010", "type": "concept", "title": "Behavior before and after speech"}, {"id": "3d809ea6-f148-4ccc-aa81-ed5263d0a184", "type": "concept", "title": "Props, furniture, and environment"}], "description": "Students honor everyday detail without becoming casual or flat."}, {"id": "b9e1b0f5-3028-4e7a-af16-ecf7f757bd84", "type": "subtopic", "title": "Listening and Silence", "children": [{"id": "22cbb22b-1504-48c8-987b-f8cbf869082c", "type": "concept", "title": "Active silence"}, {"id": "08c7291d-f4e3-4b7c-94cb-1364759b946f", "type": "concept", "title": "Interruptions, overlaps, and pauses"}, {"id": "c8e5ee98-d1c8-43bb-a1e7-2623db1c32b9", "type": "concept", "title": "Listening as action"}], "description": "Realism often lives in what happens between lines."}, {"id": "ea58dde2-0f7e-4524-b4f5-e3bbe5a54f3c", "type": "subtopic", "title": "Natural Behavior, Theatrical Shape", "children": [{"id": "ace1edad-28bb-4aa5-a715-8149b83043dc", "type": "concept", "title": "Pacing and rhythm"}, {"id": "2571143b-1816-427b-abae-f6df96de0497", "type": "concept", "title": "Focus and visibility"}, {"id": "59a1a3e4-736a-4ed4-bf76-dc86c4c02dc1", "type": "concept", "title": "Avoiding underpowered realism"}], "description": "The unit balances truthful life with stage clarity."}]}, {"id": "6bb693f6-b07a-4c04-baf7-76bc1de36709", "type": "topic", "title": "Emotional Life and Truth", "description": "Actors learn to create emotional availability safely and repeatably. The aim is truthful behavior under circumstances, not forced feeling.", "children": [{"id": "3d82dd56-9399-407a-abcf-2bf261b05ad0", "type": "subtopic", "title": "Imagination and Personalization", "children": [{"id": "15ba4429-c5db-4bef-a872-824e359d029c", "type": "concept", "title": "As-if work"}, {"id": "66cabc72-25de-4070-8a6c-7def44668633", "type": "concept", "title": "Sensory anchors"}, {"id": "184eac14-a272-47ae-990e-c1f61ae5cc4a", "type": "concept", "title": "Personalization with boundaries"}], "description": "Students find imaginative access without unsafe disclosure."}, {"id": "5b678672-d3c7-4d25-8bc7-12737a496dbd", "type": "subtopic", "title": "Repeatability", "children": [{"id": "8a48b2f3-348e-4425-a04a-09af7ba15d45", "type": "concept", "title": "Preparation rituals"}, {"id": "84b7422d-e557-4e3f-98f9-625f59c5473a", "type": "concept", "title": "Breath, body, and focus cues"}, {"id": "c879a654-5abc-49f1-88c0-e5c00ddc8ee5", "type": "concept", "title": "Recovering when emotion is different each run"}], "description": "Performance requires reliable access across rehearsals and showings."}, {"id": "3b9686b3-b801-4eb8-87d2-9471dbf775e5", "type": "subtopic", "title": "Ethical Emotional Work", "children": [{"id": "9a80480b-d84d-41d7-afee-d6a2b0113900", "type": "concept", "title": "No pressure to reveal trauma"}, {"id": "5e25d617-d935-4462-882a-521eb53573e5", "type": "concept", "title": "Return-to-neutral techniques"}, {"id": "dc385ca8-2ccb-4f4e-af20-1ec3caa0a95f", "type": "concept", "title": "When to stop, pause, or adjust material"}], "description": "The course treats emotional craft as consent-aware practice."}]}, {"id": "15c86366-4433-45a8-8744-0f5bc9cf2a0f", "type": "topic", "title": "Working Moment-to-Moment", "description": "This unit trains actors to stop pre-planning results and respond truthfully to the partner, room, and given circumstances.", "children": [{"id": "74cc337a-5023-4b0c-b0a5-734bf20c978c", "type": "subtopic", "title": "Partner Response", "children": [{"id": "4419aaa2-9266-4ba8-9a7d-630a076296a7", "type": "concept", "title": "Listening with the whole body"}, {"id": "c6e05240-b96f-4a8b-9578-7fe761db501a", "type": "concept", "title": "Taking in before responding"}, {"id": "d2f7b8f5-2c51-4ddf-a6cb-812459022c58", "type": "concept", "title": "Allowing surprise"}], "description": "The partner becomes the source of behavior."}, {"id": "1a9a10f5-70b6-44e0-9025-5ab5680fd030", "type": "subtopic", "title": "Impulse and Adaptation", "children": [{"id": "fe822f5e-30dc-4d55-bddb-7d7a8e6aa6d0", "type": "concept", "title": "Impulse versus habit"}, {"id": "76e5c7e6-3afd-456b-ba08-0214fd602801", "type": "concept", "title": "Adjusting tactics"}, {"id": "b2fbe4f9-9585-4dbe-ba4d-1b7e7ead0baf", "type": "concept", "title": "Staying available after mistakes"}], "description": "Students practice following impulses through craft structure."}, {"id": "7fb91b71-cf6a-4342-9d9e-6782f62a8b0e", "type": "subtopic", "title": "Repetition and Presence", "children": [{"id": "7582921f-f943-4d83-a63e-6bab8da55f9a", "type": "concept", "title": "Repetition exercises"}, {"id": "90133525-294b-447d-b8c0-79922982f662", "type": "concept", "title": "Independent activity"}, {"id": "e27eb5b9-d64d-4b83-8ef4-e985eda83652", "type": "concept", "title": "Reality of doing"}], "description": "Meisner-based tools sharpen attention and truthful exchange."}]}, {"id": "7711b0b7-c4dd-46c8-9a3a-be49f087387a", "type": "topic", "title": "Subtext", "description": "Subtext gives scenes tension and depth. Students learn to act what is wanted, hidden, avoided, or implied beneath the literal words.", "children": [{"id": "f917301e-c3cc-4d5b-891e-0356b5686859", "type": "subtopic", "title": "What Is Unsaid", "children": [{"id": "6ad84079-c86c-4c35-b22e-399cb1efcb9b", "type": "concept", "title": "Avoidance, denial, desire, shame, threat, and longing"}, {"id": "3015a8fb-c37b-4355-a91c-4193c3699160", "type": "concept", "title": "Contradiction between words and action"}, {"id": "cd860d9d-464f-43fb-9f8c-d2e9a9b0f00e", "type": "concept", "title": "Secrets and withheld information"}], "description": "Students identify hidden needs and pressures."}, {"id": "9604a2e0-5274-4028-b946-d11efa077399", "type": "subtopic", "title": "Subtext Through Behavior", "children": [{"id": "79c7fcf2-5922-46ed-a42f-cd5e3bf88620", "type": "concept", "title": "Gesture, pace, silence, eye contact, and distance"}, {"id": "53657361-a90f-466c-a840-86ff9d27397d", "type": "concept", "title": "Changing tactics to conceal or reveal"}, {"id": "1e1d815e-0f92-4406-9fe6-0f76068f1d3d", "type": "concept", "title": "Objects and environment as cover"}], "description": "Actors show subtext by doing, not explaining."}, {"id": "5887484f-21ba-4b6b-be3b-102ffcce96f7", "type": "subtopic", "title": "Textual Evidence", "children": [{"id": "f35b1764-f925-42d7-ac82-34d44e3f2c31", "type": "concept", "title": "Repeated words"}, {"id": "74b67eee-6ad3-4c46-8be0-5505f545d5cf", "type": "concept", "title": "Punctuation and interruptions"}, {"id": "2d27cbe9-12ab-4a44-8efe-acfb87dc1ba7", "type": "concept", "title": "Scene events and relationship history"}], "description": "Choices stay grounded in the script."}]}, {"id": "924cc5bb-0331-416d-98e5-bdbe571d5ed6", "type": "topic", "title": "Physical and Vocal Choices", "description": "Acting II integrates character analysis with body and voice so choices become specific, visible, audible, and sustainable.", "children": [{"id": "6cbd76e7-ad29-4d3a-9e3f-d6e29c7a3c76", "type": "subtopic", "title": "Physical Score", "children": [{"id": "cb5ce7de-e5d1-4199-95b8-e654c3aa4289", "type": "concept", "title": "Posture, rhythm, gesture, stillness, and spatial use"}, {"id": "aa961331-494d-4cb3-863a-ebdaf49f1262", "type": "concept", "title": "Entrances, exits, and transitions"}, {"id": "45ed4faf-e2ab-4edd-9e53-f1866c109503", "type": "concept", "title": "Physical behavior under pressure"}], "description": "Students design repeatable movement choices for character and scene."}, {"id": "48ff3f75-79ff-446d-bbf2-7af496ad7078", "type": "subtopic", "title": "Vocal Score", "children": [{"id": "e8ebe59a-b6c8-4b36-bbd4-7e5a9b76541d", "type": "concept", "title": "Pace, volume, pitch, resonance, articulation, and silence"}, {"id": "25900d87-606e-4d5c-851f-9969788dbb1f", "type": "concept", "title": "Operative words and phrasing"}, {"id": "6e821128-06a7-4211-bb92-cee5c4bf6814", "type": "concept", "title": "Vocal shifts at beat changes"}], "description": "Voice reveals thought, relationship, status, and stakes."}, {"id": "9639fd9b-e202-444b-9ed7-a398d0f6bb07", "type": "subtopic", "title": "Integration With Objective", "children": [{"id": "ff016a8f-d40f-45ae-9b74-8ec1a05a55d3", "type": "concept", "title": "Choice connected to tactic"}, {"id": "bc45915a-a331-47ae-b62f-e4a2cd467ed3", "type": "concept", "title": "Avoiding decorative movement"}, {"id": "4957c32b-2e0f-429a-b92a-472bd6293c0e", "type": "concept", "title": "Adjusting choices based on partner response"}], "description": "Physical and vocal choices must serve action."}]}, {"id": "6bc39692-d84a-4979-9a2a-11b494b3fd12", "type": "topic", "title": "The Rehearsal Process", "description": "An Acting II course teaches students how to rehearse independently, take notes, revise choices, and collaborate with discipline.", "children": [{"id": "323a3f8d-7183-4f22-b34f-102353be0130", "type": "subtopic", "title": "Independent Rehearsal", "children": [{"id": "62df4a19-263b-4f71-b4ed-3a2b83634861", "type": "concept", "title": "Scheduling, goals, run logs, and partner agreements"}, {"id": "814217a7-fc97-4668-8edf-b73a09f9f5f2", "type": "concept", "title": "Memorization and line security"}, {"id": "0a3e2bdc-ef2b-4b16-8467-ba9dc78a92bf", "type": "concept", "title": "Trying alternatives before settling"}], "description": "Students learn to make progress outside class."}, {"id": "7dc5036a-0dff-4d4b-84b1-4b4e3863ca61", "type": "subtopic", "title": "Notes and Revision", "children": [{"id": "c5297472-5917-476c-84cb-2d321387d55e", "type": "concept", "title": "Receiving notes without defensiveness"}, {"id": "352a867e-67d0-4010-b8b2-4e13f2c919a6", "type": "concept", "title": "Translating notes into actions"}, {"id": "0311546d-ff2e-439f-b0c6-0776e0d2196e", "type": "concept", "title": "Tracking changes across runs"}], "description": "The unit turns critique into playable adjustments."}, {"id": "6563e869-4212-4c73-8668-06bc339ce64d", "type": "subtopic", "title": "Professional Room Habits", "children": [{"id": "9a12b4b7-417e-455d-948a-6986e36b4e84", "type": "concept", "title": "Punctuality, preparation, boundaries, and communication"}, {"id": "f340b199-58c6-447b-8ba8-8edc4af81af8", "type": "concept", "title": "Respect for scene partners"}, {"id": "71a5e212-0f09-4c38-ad64-6e3a618890be", "type": "concept", "title": "Consent and staging adjustments"}], "description": "Rehearsal etiquette is part of craft."}]}, {"id": "e6aa46a1-1762-4a05-a9d7-901e49bfc507", "type": "topic", "title": "Scene Presentation", "description": "The final presentation tests whether analysis, rehearsal, emotional truth, subtext, and physical/vocal specificity can live in performance.", "children": [{"id": "7150e6d0-3513-4d95-807a-16ebc0eaa1aa", "type": "subtopic", "title": "Polishing Without Freezing", "children": [{"id": "ad9213a2-1bad-437d-bfcd-494f7107a047", "type": "concept", "title": "Repeatability with freshness"}, {"id": "76447653-b6be-4592-971c-da343ecf27aa", "type": "concept", "title": "Clear beginning, middle, and end"}, {"id": "02a37329-4d8a-49c2-8bd4-b205eec4fafa", "type": "concept", "title": "Transitions and final beat"}], "description": "Students keep choices alive while making the scene stage-ready."}, {"id": "16113af3-3f6b-4645-8b5c-312873449980", "type": "subtopic", "title": "Audience Relationship", "children": [{"id": "045e600d-117d-4f85-ba77-251c5092404a", "type": "concept", "title": "Focus, projection, visibility, and energy"}, {"id": "ee7ffcc1-65fc-40ad-988d-1cd34c017bbe", "type": "concept", "title": "Staying with partner under pressure"}, {"id": "80a5c0a6-72b3-481f-a57f-64c69c018022", "type": "concept", "title": "Recovery from mistakes"}], "description": "Actors adjust to being watched without performing at the audience."}, {"id": "160442b1-4584-4548-9502-b58052120dcb", "type": "subtopic", "title": "Post-Performance Reflection", "children": [{"id": "b5ea8224-8b36-475f-a656-fb1793451069", "type": "concept", "title": "Craft-based self-assessment"}, {"id": "fb801df1-50e5-4bea-ab26-68112823ff0c", "type": "concept", "title": "Peer and instructor response"}, {"id": "b5e166c1-ac12-4e9c-bc78-6e0de04ef81e", "type": "concept", "title": "Next steps for Acting III, auditions, and production work"}], "description": "The showing becomes evidence for future training."}]}], "dbBacked": true}$act2json$::jsonb,
